ALTER TABLE "company_info" ADD COLUMN "companyPage" JSONB NOT NULL DEFAULT '{}';

-- Текущие тексты страницы «О компании» (были зашиты в вёрстку) — в базу,
-- чтобы в админке они уже были заполнены.
UPDATE "company_info" SET "companyPage" = '{"philosophyTag": "— Философия", "philosophyTitle": "Мы не продаем туры — мы дарим опыт", "philosophyText": "Мы команда ребят влюбленных в свой край, которые хотят подарить вам хорошие впечатления и эмоции от наших поездок, походов и восхождений.\n\nКамчатка - уникальный край, полный контрастов и совсем не похожий на остальную страну. Здесь можно получить бесконечное количество новых впечатлений, преодолеть себя и почувствовать истинный вкус жизни!\n\nНаша главная цель - подарить вам эмоции и показать наши уникальные места.", "philosophyImage": "", "historyTag": "— История", "historyTitle": "Как мы росли"}'::jsonb;

UPDATE "company_info" SET "history" = '[{"year": "2026", "title": "Новый сезон", "text": "Прошли повышение квалификации и аттестацию — теперь все инструкторы-проводники сертифицированы по горному и пешему туризму.", "current": true}, {"year": "2025", "title": "2500+ туристов", "text": "Расширение маршрутов до Командорских островов и зимних туров.", "current": false}, {"year": "2024", "title": "Новые маршруты", "text": "Новый маршрут — Ксудач. Вертолётные туры. Команда из 8 профессионалов.", "current": false}, {"year": "2023", "title": "Экспедиции на Эльбрус", "text": "Экспедиция стала настоящим прорывом — команда покорила вершину и открыла для себя силу гор. Следующий вызов уже ждёт: Килиманджаро.", "current": false}, {"year": "2022", "title": "Рейтинг 4.9", "text": "Средняя оценка на Яндекс и Tripadvisor. Команда расширяется, запускаем семейные туры.", "current": false}, {"year": "2021", "title": "1000 туристов", "text": "Тысячный гость. Открываем туры на Долину гейзеров и Курильское озеро.", "current": false}, {"year": "2020", "title": "Первые туры", "text": "12 групп, 84 туриста. Запускаем маршрут на Авачинский и Мутновский.", "current": false}, {"year": "2019", "title": "МЧС сертификация", "text": "Все гиды получают официальную сертификацию МЧС.", "current": false}, {"year": "2018", "title": "Основание компании", "text": "Трое друзей, вдохновлённых родным краем и горными походами, решили основать компанию и открыть эти вершины для всех.", "current": false}]'::jsonb WHERE "history" IS NULL;
